/**
 * Test failed suspend/resume via ComputeService which depends on
 * Admin extension being installed in OpenStack. Throws UOE if extension is missing.
 */
@Test(expectedExceptions = UnsupportedOperationException.class)
public void testSuspendWithoutAdminExtensionThrowsUOE() throws Exception {
    HttpRequest suspendServer = HttpRequest.builder().method("POST").endpoint("https://az-1.region-a.geo-1.compute.hpcloudsvc.com/v2/3456/servers/71752/action").addHeader("X-Auth-Token", authToken).payload(payloadFromStringWithContentType("{\"suspend\":null}", "application/json")).build();
    HttpResponse suspendServerResponse = HttpResponse.builder().statusCode(202).build();
    HttpResponse serverDetailSuspendedResponse = HttpResponse.builder().statusCode(200).payload(payloadFromResource("/server_details_suspended.json")).build();
    Map<HttpRequest, HttpResponse> requestResponseMap = ImmutableMap.<HttpRequest, HttpResponse>builder().put(keystoneAuthWithUsernameAndPasswordAndTenantName, responseWithKeystoneAccess).put(extensionsOfNovaRequest, unmatchedExtensionsOfNovaResponse).put(listDetail, listDetailResponse).put(listFlavorsDetail, listFlavorsDetailResponse).put(suspendServer, suspendServerResponse).put(serverDetail, serverDetailSuspendedResponse).build();
    Injector forAdminExtension = requestsSendResponses(requestResponseMap);
    ComputeService compute = forAdminExtension.getInstance(ComputeService.class);
    compute.suspendNode("az-1.region-a.geo-1/71752");
}

