@Test
public void testFindImageWithIdDefaultToGetImageStrategyAndPopulatesTheCache() {
    final Supplier<Set<? extends Location>> locations = Suppliers.<Set<? extends Location>>ofInstance(ImmutableSet.<Location>of(region));
    final Supplier<Set<? extends Image>> images = Suppliers.<Set<? extends Image>>ofInstance(ImmutableSet.<Image>of(new ImageBuilder().ids("Ubuntu 11.04 x64").name("Ubuntu 11.04 x64").description("Ubuntu 11.04 x64").location(region).status(Status.AVAILABLE).operatingSystem(OperatingSystem.builder().name("Ubuntu 11.04 x64").description("Ubuntu 11.04 x64").is64Bit(true).version("11.04").family(OsFamily.UBUNTU).build()).build(), new ImageBuilder().ids("Ubuntu 11.04 64-bit").name("Ubuntu 11.04 64-bit").description("Ubuntu 11.04 64-bit").location(region).status(Status.AVAILABLE).operatingSystem(OperatingSystem.builder().name("Ubuntu 11.04 64-bit").description("Ubuntu 11.04 64-bit").is64Bit(true).version("11.04").family(OsFamily.UBUNTU).build()).build()));
    final Supplier<Set<? extends Hardware>> hardwares = Suppliers.<Set<? extends Hardware>>ofInstance(ImmutableSet.<Hardware>of(new HardwareBuilder().ids(String.format("datacenter(%s)platform(%s)cpuCores(%d)memorySizeMB(%d)diskSizeGB(%d)", "Falkenberg", "Xen", 1, 512, 5)).ram(512).processors(ImmutableList.of(new Processor(1, 1.0))).volumes(ImmutableList.<Volume>of(new VolumeImpl((float) 5, true, true))).hypervisor("Xen").location(region).supportsImage(ImagePredicates.idEquals(image.getId())).build()));
    final Provider<TemplateOptions> optionsProvider = new Provider<TemplateOptions>() {

        @Override
        public TemplateOptions get() {
            return new TemplateOptions();
        }
    };
    final GetImageStrategy getImageStrategy = createMock(GetImageStrategy.class);
    expect(getImageStrategy.getImage(image.getId())).andReturn(image);
    replay(getImageStrategy);
    Provider<TemplateBuilder> templateBuilderProvider = new Provider<TemplateBuilder>() {

        @Override
        public TemplateBuilder get() {
            return createTemplateBuilder(null, locations, images, hardwares, region, optionsProvider, this, getImageStrategy);
        }
    };
    TemplateBuilder templateBuilder = templateBuilderProvider.get();
    try {
        // First call searching for the image properties will fail, as the image is not in the cache
        templateBuilder.osNameMatches(image.getOperatingSystem().getName()).build();
        fail("Image should not exist in the cache");
    } catch (Exception ex) {
        // Expected path
    }
    // A second call using the imageId will fallback to the GetImageStrategy and populate the image in the cache.
    assertNotNull(templateBuilder.imageId(image.getId()).build());
    // The third call will succeed, as the previous one should have populated the image in the cache.
    // Clear all criteria
    templateBuilder.imageId(null);
    Template template = templateBuilder.osNameMatches(image.getOperatingSystem().getName()).build();
