@Test
public void testCompareCidrBlocks() {
    final IpPermission tcp = builder().ipProtocol(IpProtocol.TCP).build();
    final IpPermission everything = builder().fromPermission(tcp).cidrBlock("0.0.0.0/0").build();
    final IpPermission universal = builder().fromPermission(tcp).cidrBlock("0.0.0.0/0").build();
    assertEqualAndComparable(everything, universal);
    final IpPermission localhost = builder().fromPermission(tcp).cidrBlock("127.0.0.1/32").build();
    final IpPermission tenTwentyOne = builder().fromPermission(tcp).cidrBlock("10.0.0.21/32").build();
    final IpPermission tenTwoHundred = builder().fromPermission(tcp).cidrBlock("10.0.0.200/32").build();
    // comparison is alphabetic, not by numeric equivalent
    assertOrder(tenTwoHundred, tenTwentyOne);
    assertTotalOrder(ImmutableList.of(tcp, everything, tenTwoHundred, tenTwentyOne, localhost));
}

