@Test(expectedExceptions = AuthorizationException.class)
@Override
public void testCorrectAuthException() throws Exception {
    ComputeServiceContext context = null;
    try {
        String credential = toStringAndClose(getClass().getResourceAsStream("/test"));
        Properties overrides = setupProperties();
        overrides.setProperty(provider + ".identity", "000000000000@developer.gserviceaccount.com");
        overrides.setProperty(provider + ".credential", credential);
        context = newBuilder().modules(ImmutableSet.of(getLoggingModule(), credentialStoreModule)).overrides(overrides).build(ComputeServiceContext.class);
        context.getComputeService().listNodes();
    } catch (AuthorizationException e) {
        throw e;
    } catch (RuntimeException e) {
        e.printStackTrace();
        throw e;
    } finally {
        if (context != null)
            context.close();
    }
}

