@Test
public void testGetVirtualGuestOperatingSystemsWithMissingReferenceCode() {
    // Malformed response leading to failure:
    // {
    //    "itemPrice": {
    //        "hourlyRecurringFee": ".131",
    //        "item": {
    //            "description": "Windows Server 2012 Datacenter Edition (64bit)"
    //        },
    //        "recurringFee": "90.63"
    //    },
    //    "template": {
    //        "id": null
    //        missing operatingSystemReferenceCode entry!
    //    }
    // },
    ContainerVirtualGuestConfigurationOption osValid = ContainerVirtualGuestConfigurationOption.builder().productItemPrice(ProductItemPrice.builder().hourlyRecurringFee(0).recurringFee("0").item(ProductItem.builder().description("CentOS - Latest").build()).build()).template(VirtualGuest.builder().operatingSystemReferenceCode("CENTOS_LATEST").build()).build();
    ContainerVirtualGuestConfigurationOption osInvalid = ContainerVirtualGuestConfigurationOption.builder().productItemPrice(ProductItemPrice.builder().hourlyRecurringFee(0.131f).recurringFee("90.63").item(ProductItem.builder().description("Windows Server 2012 Datacenter Edition (64bit)").build()).build()).template(VirtualGuest.builder().build()).build();
    ContainerVirtualGuestConfiguration conf = ContainerVirtualGuestConfiguration.builder().blockDevices(ImmutableSet.<ContainerVirtualGuestConfigurationOption>of()).datacenters(ImmutableSet.<ContainerVirtualGuestConfigurationOption>of()).memory(ImmutableSet.<ContainerVirtualGuestConfigurationOption>of()).networkComponents(ImmutableSet.<ContainerVirtualGuestConfigurationOption>of()).operatingSystems(ImmutableSet.<ContainerVirtualGuestConfigurationOption>of(osValid, osInvalid)).processors(ImmutableSet.<ContainerVirtualGuestConfigurationOption>of()).build();
    Set<OperatingSystem> virtualGuestOperatingSystems = conf.getVirtualGuestOperatingSystems();
    OperatingSystem os = Iterables.getOnlyElement(virtualGuestOperatingSystems);
    assertEquals(os.getOperatingSystemReferenceCode(), osValid.getTemplate().getOperatingSystemReferenceCode());
}

